        className: "language-typescript",
        children: "// TypeScript simulation of SQL query execution\ninterface Employee {\n  id: number;\n  name: string;\n  departmentId: number;\n  salary: number;\n}\n\ninterface Department {\n  id: number;\n  name: string;\n  location: string;\n}\n\n// SQL: SELECT d.name, AVG(e.salary) as avg_salary\n//      FROM employees e\n//      JOIN departments d ON e.departmentId = d.id\n//      GROUP BY d.name\n//      HAVING AVG(e.salary) > 50000;\n\nfunction getDepartmentsAboveAvgSalary(\n  employees: Employee[],\n  departments: Department[]\n): { name: string; avgSalary: number }[] {\n  const deptMap = new Map(departments.map(d => [d.id, d]));\n\n  // Group by department\n  const grouped = new Map<number, number[]>();\n  for (const emp of employees) {\n    const list = grouped.get(emp.departmentId) || [];\n    list.push(emp.salary);\n    grouped.set(emp.departmentId, list);\n  }\n\n  const result: { name: string; avgSalary: number }[] = [];\n  for (const [deptId, salaries] of grouped) {\n    const avgSalary = salaries.reduce((a, b) => a + b, 0) / salaries.length;\n    if (avgSalary > 50000) {\n      result.push({ name: deptMap.get(deptId)?.name || \"Unknown\", avgSalary });\n    }\n  }\n  return result;\n}\n"
