        children: "// Round Robin CPU Scheduling Simulation\ninterface Process {\n  id: number;\n  arrivalTime: number;\n  burstTime: number;\n  remainingTime: number;\n  completionTime: number;\n  turnaroundTime: number;\n  waitingTime: number;\n}\n\nfunction roundRobinScheduling(processes: Process[], quantum: number): Process[] {\n  const queue: Process[] = [...processes];\n  let currentTime = 0;\n  const completed: Process[] = [];\n\n  while (queue.length > 0) {\n    const process = queue.shift()!;\n    const executeTime = Math.min(quantum, process.remainingTime);\n    currentTime += executeTime;\n    process.remainingTime -= executeTime;\n\n    if (process.remainingTime === 0) {\n      process.completionTime = currentTime;\n      process.turnaroundTime = process.completionTime - process.arrivalTime;\n      process.waitingTime = process.turnaroundTime - process.burstTime;\n      completed.push(process);\n    } else {\n      // Check if any new process arrived during execution\n      queue.push(process); // Re-add to end of queue\n    }\n  }\n  return completed;\n}\n\n// Calculate average turnaround time\nfunction avgTurnaroundTime(processes: Process[]): number {\n  return processes.reduce((sum, p) => sum + p.turnaroundTime, 0) / processes.length;\n}\n"
