        className: "language-typescript",
        children: "// Subnet Calculator in TypeScript\nclass IPv4Address {\n  constructor(\n    public octets: [number, number, number, number],\n    public prefixLength: number\n  ) {}\n\n  getNetworkAddress(): string {\n    const mask = this.getSubnetMask();\n    return this.octets.map((octet, i) => octet & mask[i]).join(\".\");\n  }\n\n  getSubnetMask(): number[] {\n    const mask: number[] = [0, 0, 0, 0];\n    for (let i = 0; i < 4; i++) {\n      const bits = Math.min(8, this.prefixLength - i * 8);\n      if (bits > 0) {\n        mask[i] = 256 - Math.pow(2, 8 - bits);\n      }\n    }\n    return mask;\n  }\n\n  getBroadcastAddress(): string {\n    const mask = this.getSubnetMask();\n    return this.octets\n      .map((octet, i) => octet | (255 - mask[i]))\n      .join(\".\");\n  }\n\n  getTotalHosts(): number {\n    return Math.pow(2, 32 - this.prefixLength) - 2;\n  }\n}\n\n// Example: 192.168.1.0/24\nconst subnet = new IPv4Address([192, 168, 1, 0], 24);\nconsole.log(subnet.getNetworkAddress());   // 192.168.1.0\nconsole.log(subnet.getBroadcastAddress()); // 192.168.1.255\nconsole.log(subnet.getTotalHosts());       // 254\n"
