        children: "// Study time allocation calculator\ninterface StudyAllocation {\n  topic: string;\n  weightage: number;     // out of 60\n  difficulty: number;     // 1-5\n  currentProficiency: number; // 1-10\n}\n\nfunction calculateHours(allocation: StudyAllocation[]): Map<string, number> {\n  const totalHours = 90; // Total study days * hours per day\n  const allocationMap = new Map<string, number>();\n\n  let totalPriority = 0;\n  const priorities = allocation.map(a => {\n    const priority = a.weightage * (10 - a.currentProficiency) * a.difficulty;\n    totalPriority += priority;\n    return { topic: a.topic, priority };\n  });\n\n  for (const p of priorities) {\n    allocationMap.set(p.topic, Math.round((p.priority / totalPriority) * totalHours));\n  }\n  return allocationMap;\n}\n"
