        children: "// Generate random simplification questions\nfunction generateSimplificationQuestion(): { question: string; answer: number } {\n  const a = Math.floor(Math.random() * 100);\n  const b = Math.floor(Math.random() * 50) + 1;\n  const operations = [\"+\", \"-\", \"×\", \"÷\"];\n  const op = operations[Math.floor(Math.random() * operations.length)];\n\n  let answer: number;\n  switch (op) {\n    case \"+\": answer = a + b; break;\n    case \"-\": answer = a - b; break;\n    case \"×\": answer = a * b; break;\n    case \"÷\": answer = Math.round((a / b) * 100) / 100; break;\n    default: answer = 0;\n  }\n\n  return {\n    question: `${a} ${op} ${b} = ?`,\n    answer,\n  };\n}\n"
